module robber_password_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    input wire [7:0] arr_8, arr_9, arr_10, arr_11, arr_12, arr_13, arr_14, arr_15,\n    input wire [3:0] length,\n    output reg [19:0] result,\n    output reg done\n);\n\n    // States\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH  = 2'd2;\n\n    // Configuration\n    localparam [19:0] MOD     = 20'd1000009;\n    localparam [3:0] MAX_LEN  = 4'd16;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [3:0] i;\n    reg [19:0] dp_i, dp_im1, dp_im2, dp_im3;\n    reg [7:0] char_array [0:15];\n    reg [7:0] prev_char, prev_prev_char;\n\n    // Vowel function\n    function automatic is_vowel(input [7:0] c);\n        begin\n            is_vowel = (c == 8'h61) || (c == 8'h65) || (c == 8'h69) || \n                       (c == 8'h6F) || (c == 8'h75);\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state         <= IDLE;\n            done          <= 1'b0;\n            result        <= 20'd0;\n            i             <= 4'd0;\n            dp_im1        <= 20'd0;\n            dp_im2        <= 20'd0;\n            dp_im3        <= 20'd0;\n            prev_char     <= 8'd0;\n            prev_prev_char <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load character array\n                        char_array[0]  <= arr_0;\n                        char_array[1]  <= arr_1;\n                        char_array[2]  <= arr_2;\n                        char_array[3]  <= arr_3;\n                        char_array[4]  <= arr_4;\n                        char_array[5]  <= arr_5;\n                        char_array[6]  <= arr_6;\n                        char_array[7]  <= arr_7;\n                        char_array[8]  <= arr_8;\n                        char_array[9]  <= arr_9;\n                        char_array[10] <= arr_10;\n                        char_array[11] <= arr_11;\n                        char_array[12] <= arr_12;\n                        char_array[13] <= arr_13;\n                        char_array[14] <= arr_14;\n                        char_array[15] <= arr_15;\n\n                        // Initialize DP values\n                        dp_im1 <= 20'd1;  // dp[0] = 1\n                        dp_im2 <= 20'd0;\n                        dp_im3 <= 20'd0;\n                        prev_char <= 8'd0;\n                        prev_prev_char <= 8'd0;\n                        i <= 4'd1;        // Start at index 1\n                        state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (i > length) begin\n                        result <= dp_im1;\n                        state <= FINISH;\n                    end else begin\n                        // Current character processing\n                        dp_i = dp_im1;  // Base case\n\n                        if (!is_vowel(char_array[i-1])) begin\n                            // Check transformation condition\n                            if ((i >= 4'd3) && \n                                (prev_char == 8'h6F) && \n                                (prev_prev_char == char_array[i-1])) \n                            begin\n                                dp_i = dp_i + dp_im3;\n                                if (dp_i >= MOD) dp_i -= MOD;\n                            end\n                        end\n\n                        // Shift history registers\n                        dp_im3 <= dp_im2;\n                        dp_im2 <= dp_im1;\n                        dp_im1 <= dp_i;\n                        prev_prev_char <= prev_char;\n                        prev_char <= char_array[i-1];\n\n                        i <= i + 4'd1;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule